package com.StudentManagementwithloginlogout.StudentManagementwithloginlogout.config;
import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.crypto.password.PasswordEncoder; import com.StudentManagementwithloginlogout.StudentManagementwithloginlogout.entity.*; import com.StudentManagementwithloginlogout.StudentManagementwithloginlogout.repository.UserRepository; import java.time.LocalDateTime;
@Configuration public class AdminInitializer { @Bean CommandLineRunner createAdmin(UserRepository repo,PasswordEncoder enc,@Value("${app.admin.email:admin@example.com}") String email,@Value("${app.admin.password:Admin@123}") String pass){return args->{if(!repo.existsByEmail(email)){User u=new User();u.setName("Admin");u.setEmail(email);u.setPassword(enc.encode(pass));u.setStatus("ACTIVE");u.setRole(Role.ADMIN);u.setCreatedDate(LocalDateTime.now());repo.save(u);}};} }
